(function(){
if(window.__QMES_RECIPE_CHEM_MASTER_V2__)return;window.__QMES_RECIPE_CHEM_MASTER_V2__=true;
const E='등록된 데이터가 없습니다.';
function table(head,cols){return `<div class="qbe-table-wrap"><table><thead><tr>${head.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody><tr><td colspan="${cols}" style="text-align:center;color:#94a3b8;padding:24px">${E}</td></tr></tbody></table></div>`}
function html(){return `<div class="qmes-business-extension qbe-chemical-master">
<div class="qbe-title-row"><div><h1 class="qbe-title">Recipe / BOM Master</h1><div class="qbe-subtitle">제품별 BOM · Recipe Revision · 표준 배합 · 공정 Routing을 통합 관리합니다.</div><div style="margin-top:5px;font-size:11px;color:#64748b">제품 → Revision → Formula / Routing → MRP → 작업지시 → 생산 LOT</div></div></div>
<div class="qbe-card" style="padding:10px 12px;margin-bottom:12px"><div style="display:flex;gap:7px;flex-wrap:wrap"><button class="qbe-primary" data-bom-act="search">조회</button><button class="qbe-primary" data-bom-act="add">+ 추가</button><button class="qbe-primary" data-bom-act="save">저장</button><button class="qbe-primary" data-bom-act="delete" style="background:#64748b">삭제</button><button class="qbe-primary" data-bom-act="copy" style="background:#475569">BOM 복사</button><button class="qbe-primary" data-bom-act="revision" style="background:#f59e0b">BOM 개정</button><button class="qbe-primary" data-bom-act="print" style="background:#475569">인쇄</button></div></div>
<div style="display:grid;grid-template-columns:minmax(250px,.55fr) minmax(600px,1.45fr);gap:12px">
<div class="qbe-card"><div class="qbe-card-head"><h2>제품 목록</h2><span class="qbe-hint">Product Master</span></div>${table(['제품코드','제품명','고객사','Grade'],4)}</div>
<div class="qbe-card"><div class="qbe-card-head"><h2>Recipe / BOM 개정 목록</h2><span class="qbe-hint">Revision History</span></div>${table(['Revision','변경내용','기준 Batch','예상수율','적용일','상태','승인'],7)}</div></div>
<div class="qbe-card"><div class="qbe-card-head"><h2>선택 BOM 기본정보</h2><span class="qbe-hint">Master Data</span></div><div class="qbe-form-grid"><div class="qbe-field"><label>제품코드</label><input placeholder="제품 선택 시 표시"></div><div class="qbe-field"><label>제품명</label><input placeholder="제품명"></div><div class="qbe-field"><label>고객사</label><input placeholder="고객사"></div><div class="qbe-field"><label>제품 Grade</label><input placeholder="Grade / 규격"></div><div class="qbe-field"><label>Recipe No.</label><input placeholder="RCP-001"></div><div class="qbe-field"><label>Revision</label><input placeholder="Rev.01"></div><div class="qbe-field"><label>기준 Batch Size (kg)</label><input type="number" placeholder="1000"></div><div class="qbe-field"><label>예상 수율 (%)</label><input type="number" placeholder="100.00"></div><div class="qbe-field"><label>적용일</label><input type="date"></div><div class="qbe-field"><label>상태</label><select><option>작성중</option><option>검토중</option><option>승인</option><option>사용중</option><option>폐기</option></select></div><div class="qbe-field"><label>변경내용</label><input placeholder="개정 사유 / 변경내용"></div><div class="qbe-field"><label>작성 / 검토 / 승인</label><input readonly placeholder="전자결재 연동"></div></div></div>
<div class="qbe-card"><div class="qbe-card-head"><div style="display:flex;gap:5px;flex-wrap:wrap" class="qbm-tabs"><button class="qbe-primary" data-tab="formula">① 표준 배합표</button><button class="qbe-primary" data-tab="routing" style="background:#64748b">② 공정조건</button><button class="qbe-primary" data-tab="ctq" style="background:#64748b">③ CTQ / 검사기준</button><button class="qbe-primary" data-tab="change" style="background:#64748b">④ 변경이력</button><button class="qbe-primary" data-tab="lot" style="background:#64748b">⑤ 생산 LOT 이력</button></div><span class="qbe-hint">화학 제조 BOM</span></div>
<div data-pane="formula"><div class="qbe-card-head"><h2>표준 배합표 (Formula)</h2><span class="qbe-hint">배합비 합계 100% 자동 검증</span></div>${table(['순번','원료코드','원료명','구분','규격/Grade','배합비 %','기준량 kg','허용오차','투입순서','투입공정','CTQ','대체원료'],12)}</div>
<div data-pane="routing" style="display:none"><div class="qbe-card-head"><h2>공정 Routing / 조건</h2><span class="qbe-hint">Recipe Revision과 함께 관리</span></div>${table(['공정순서','공정명','설비','시간','RPM','온도','압력','관리기준','검사'],9)}</div>
<div data-pane="ctq" style="display:none"><div class="qbe-card-head"><h2>CTQ / 검사기준 연계</h2><span class="qbe-hint">PQC · OQC 연결</span></div>${table(['검사항목','규격','단위','검사단계','측정방법','CTQ','검사기준 연결'],7)}</div>
<div data-pane="change" style="display:none"><div class="qbe-card-head"><h2>Revision / 변경관리</h2><span class="qbe-hint">4M 변경 연계</span></div>${table(['Revision','적용일','변경 전','변경 후','변경사유','4M','작성자','승인상태'],8)}</div>
<div data-pane="lot" style="display:none"><div class="qbe-card-head"><h2>생산 LOT 적용 이력</h2><span class="qbe-hint">LOT Traceability</span></div>${table(['생산일','작업지시','생산 LOT','Revision','계획량','실적량','원료 LOT','PQC','OQC'],9)}</div></div>
<div class="qbe-card"><div class="qbe-card-head"><h2>다단계 BOM / 중간배치 구조</h2><span class="qbe-hint">완제품 → 중간배치 → 원료</span></div><div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;font-size:13px;font-weight:800"><span class="qbe-status blue">완제품</span><b>→</b><span class="qbe-status orange">중간배치 (선택)</span><b>→</b><span class="qbe-status green">원료 / 첨가제</span><span style="color:#64748b;font-weight:600">중간배치가 없는 제품은 원료를 완제품 BOM에 직접 연결합니다.</span></div></div>
</div>`}
function wire(host){host.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{const id=b.dataset.tab;host.querySelectorAll('[data-pane]').forEach(p=>p.style.display=p.dataset.pane===id?'block':'none');host.querySelectorAll('[data-tab]').forEach(x=>x.style.background=x===b?'#2563eb':'#64748b')});host.querySelector('[data-bom-act="print"]')?.addEventListener('click',()=>window.print());host.querySelectorAll('[data-bom-act]').forEach(b=>{if(b.dataset.bomAct==='print')return;b.onclick=()=>alert('BOM '+b.textContent.trim()+' 기능은 다음 단계에서 DB/API 저장과 연결합니다.')})}
function patch(){const host=document.getElementById('qmes-business-extension-host');if(!host)return;const title=host.querySelector('.qbe-title,h1');if(!title||!title.textContent.includes('Recipe / BOM Master'))return;if(host.dataset.chemicalBomV2==='1')return;host.dataset.chemicalBomV2='1';host.innerHTML=html();wire(host)}
new MutationObserver(patch).observe(document.documentElement,{childList:true,subtree:true});document.addEventListener('click',e=>{if(e.target.closest('[data-qbe-menu="recipe"]'))setTimeout(patch,80)},true);setInterval(patch,700);
})();